import { AccrualPosition, getChainAddresses, Position, PreLiquidationParams, PreLiquidationPosition, } from "@morpho-org/blue-sdk";
import { getChainId, readContract } from "viem/actions";
import { blueAbi, blueOracleAbi, preLiquidationAbi } from "../abis.js";
import { readContractRestructured } from "../utils.js";
import { fetchMarket } from "./Market.js";
// biome-ignore lint/complexity/useMaxParams: TODO refactor to ≤2 params
export async function fetchPosition(user, marketId, client, parameters = {}) {
    parameters.chainId ??= await getChainId(client);
    const { morpho } = getChainAddresses(parameters.chainId);
    const position = await readContractRestructured(client, {
        ...parameters,
        address: morpho,
        abi: blueAbi,
        functionName: "position",
        args: [marketId, user],
    });
    return new Position({
        user,
        marketId,
        ...position,
    });
}
// biome-ignore lint/complexity/useMaxParams: TODO refactor to ≤2 params
export async function fetchPreLiquidationParams(preLiquidation, client, parameters = {}) {
    parameters.chainId ??= await getChainId(client);
    const { preLltv, preLIF1, preLIF2, preLCF1, preLCF2, preLiquidationOracle } = await readContract(client, {
        ...parameters,
        address: preLiquidation,
        abi: preLiquidationAbi,
        functionName: "preLiquidationParams",
    });
    return new PreLiquidationParams({
        preLltv,
        preLCF1,
        preLCF2,
        preLIF1,
        preLIF2,
        preLiquidationOracle,
    });
}
// biome-ignore lint/complexity/useMaxParams: TODO refactor to ≤2 params
export async function fetchAccrualPosition(user, marketId, client, parameters = {}) {
    parameters.chainId ??= await getChainId(client);
    const [position, market] = await Promise.all([
        fetchPosition(user, marketId, client, parameters),
        fetchMarket(marketId, client, parameters),
    ]);
    return new AccrualPosition(position, market);
}
// biome-ignore lint/complexity/useMaxParams: TODO refactor to ≤2 params
export async function fetchPreLiquidationPosition(user, marketId, preLiquidation, client, parameters = {}) {
    parameters.chainId ??= await getChainId(client);
    const [position, market, preLiquidationParams] = await Promise.all([
        fetchPosition(user, marketId, client, parameters),
        fetchMarket(marketId, client, parameters),
        fetchPreLiquidationParams(preLiquidation, client, parameters),
    ]);
    const preLiquidationOraclePrice = await readContract(client, {
        ...parameters,
        address: preLiquidationParams.preLiquidationOracle,
        abi: blueOracleAbi,
        functionName: "price",
    }).catch(() => undefined);
    return new PreLiquidationPosition({
        ...position,
        preLiquidationParams,
        preLiquidation,
        preLiquidationOraclePrice,
    }, market);
}
